 function advance(ms) {
   const target = now() + ms;
   const realNow = Date.now();
   for (let guard = 0; guard < 500; guard++) {
     const next = dueActions()[0];
     if (!next || next.at > target) break;
     S.offset = Math.max(S.offset, next.at - realNow);
     next.run();
   }
   S.offset = target - realNow;
 }

